def maxNetworkRank(n, roads):
    deg = [0] * n
    link = set()
    for a, b in roads:
        deg[a] += 1
        deg[b] += 1
        link.add((min(a, b), max(a, b)))
    best = 0
    for i in range(n):
        for j in range(i + 1, n):
            rank = deg[i] + deg[j] - (1 if (i, j) in link else 0)
            if rank > best:
                best = rank
    return best
